/* ================= РОЛИ ПЕРСОНАЛА (по сериям) ================= */

export const ROLE_NAMES: Record<StaffRole, string> = {
  techdir: 'Техдиректор', aero: 'Шеф аэродинамики', mechanic: 'Главный механик', engineer: 'Гоночный инженер',
};

/** Гоночных инженеров — по числу пилотов в команде (у каждого пилота свой).
 *  Ф2/Ф3: без шефа аэро (серийная техника). Шефа стратегии нет нигде. */
export function staffRolesFor(sid: SeriesId, nDrivers: number): StaffRole[] {
  const nEng = Math.max(1, nDrivers);
  const eng: StaffRole[] = Array(nEng).fill('engineer');
  if (sid === 'f2' || sid === 'f3') return ['techdir', 'mechanic', ...eng];
  return ['techdir', 'aero', 'mechanic', ...eng];
}

/* ================= КОМАНДЫ ================= */

let teamN = 0;
function T(id: string, sid: SeriesId, name: string, short: string, color: string, color2: string,
  engineMaker: string, works: boolean, base: number, aero: number, chassis: number, power: number, tires: number,
  budget: number, rep: number): Team {
  teamN++;
  return {
    id, seriesId: sid, name, short, color, color2, engineMaker, works,
    base, aero, chassis, power, tires, wear: 0, budget, reputation: rep, capSpent: 0,
    staffIds: [], setups: {},
  };
}

