export const JUNIOR_FIRST = ['Марк', 'Энцо', 'Тео', 'Луи', 'Дани', 'Артём', 'Колин', 'Ян', 'Матео', 'Оскар', 'Хуго', 'Финн', 'Рико', 'Ной', 'Алекс', 'Ким', 'Рео', 'Себа', 'Юки', 'Арвид'];
export const JUNIOR_LAST = ['Соланер', 'Фабр', 'Крамер', 'Верне', 'Кинт', 'Ветров', 'Бри', 'Собо', 'Руччи', 'Хальм', 'Моран', 'Дюбуа', 'Кляйн', 'Росси', 'Линд', 'Харт', 'Новак', 'Бьянки', 'Окада', 'Валье'];

export function makeStaff(t: Team, rnd: () => number): Staff[] {
  const nDrivers = DRIVERS.filter((d) => d.teamId === t.id).length || 2;
  const roles = staffRolesFor(t.seriesId, nDrivers);
  const pre = F1_STAFF.filter((s) => s[3] === t.id);
  const out: Staff[] = [];
  roles.forEach((role, i) => {
    const found = pre.find((p) => p[1] === role && !out.some((o) => o.name === p[0]));
    if (found) { out.push(S(found[0], found[1], found[2], t.id, found[4])); return; }
    const base = t.reputation * 0.55 + 30 + rnd() * 18;
    const skill = Math.round(Math.min(96, Math.max(42, base - i * 4)));
    const fn = JUNIOR_FIRST[Math.floor(rnd() * JUNIOR_FIRST.length)];
    const ln = JUNIOR_LAST[Math.floor(rnd() * JUNIOR_LAST.length)];
    out.push(S(`${fn} ${ln}`, role, skill, t.id, Math.round(skill * skill * 220)));
  });
  return out;
}

